package nodepb

import (
	"testing"

	"google.golang.org/protobuf/proto"
)

// covMessage is every generated message: a proto.Message that also has the
// String(), Reset(), ProtoMessage() and Descriptor() methods generated by
// protoc-gen-go.
type covMessage interface {
	proto.Message
	String() string
	Reset()
	ProtoMessage()
	Descriptor() ([]byte, []int)
}

// nodeRoundTrip marshals m, unmarshals into fresh, and asserts proto.Equal,
// while also exercising String() and Reset().
func nodeRoundTrip[T covMessage](t *testing.T, m T, fresh T) {
	t.Helper()
	_ = m.ProtoReflect()
	m.ProtoMessage()
	if d, _ := m.Descriptor(); len(d) == 0 {
		t.Fatalf("empty descriptor")
	}
	name := proto.MessageName(m)
	if name == "" {
		t.Fatalf("empty message name")
	}
	b, err := proto.Marshal(m)
	if err != nil {
		t.Fatalf("marshal %s: %v", name, err)
	}
	if err := proto.Unmarshal(b, fresh); err != nil {
		t.Fatalf("unmarshal %s: %v", name, err)
	}
	if !proto.Equal(m, fresh) {
		t.Fatalf("round trip mismatch for %s:\n got %v\nwant %v", name, fresh, m)
	}
	_ = m.String()
	m.Reset()
}

func TestNodeGenCoverage(t *testing.T) {
	getManReq := &GetManifestRequest{}

	port := &Port{Id: "p", Mime: []string{"text/plain"}, Label: "L", Required: true, Variadic: true, Min: 1, Max: 9}
	if port.GetId() != "p" || len(port.GetMime()) != 1 || port.GetLabel() != "L" || !port.GetRequired() || !port.GetVariadic() || port.GetMin() != 1 || port.GetMax() != 9 {
		t.Fatal("Port getters")
	}

	man := &Manifest{
		Id:             "m",
		Version:        "v",
		Label:          "L",
		Color:          "#000",
		ExecutionModel: "sync",
		ProcessModel:   "single",
		Inputs:         []*Port{port},
		Outputs:        []*Port{port},
		ParamsSchema:   []byte(`{"type":"object"}`),
		Idempotent:     true,
		RetryPolicy:    "none",
		CompatibleWith: []string{"other"},
	}
	if man.GetId() != "m" || man.GetVersion() != "v" || man.GetLabel() != "L" || man.GetColor() != "#000" ||
		man.GetExecutionModel() != "sync" || man.GetProcessModel() != "single" || len(man.GetInputs()) != 1 ||
		len(man.GetOutputs()) != 1 || string(man.GetParamsSchema()) != `{"type":"object"}` || !man.GetIdempotent() ||
		man.GetRetryPolicy() != "none" || len(man.GetCompatibleWith()) != 1 {
		t.Fatal("Manifest getters")
	}

	ref := &Ref{Mime: "text/plain", Ref: "file:///x", Inline: []byte("hi")}
	if ref.GetMime() != "text/plain" || ref.GetRef() != "file:///x" || string(ref.GetInline()) != "hi" {
		t.Fatal("Ref getters")
	}

	job := &Job{
		JobId:   "j",
		GraphId: "g",
		NodeId:  "n",
		TraceId: "tr",
		SpanId:  "sp",
		Input:   map[string]*Ref{"in": ref},
		Params:  []byte(`{"k":1}`),
		Env:     map[string]string{"E": "1"},
		Cleanup: "rm",
	}
	if job.GetJobId() != "j" || job.GetGraphId() != "g" || job.GetNodeId() != "n" || job.GetTraceId() != "tr" ||
		job.GetSpanId() != "sp" || job.GetInput()["in"] == nil || string(job.GetParams()) != `{"k":1}` ||
		job.GetEnv()["E"] != "1" || job.GetCleanup() != "rm" {
		t.Fatal("Job getters")
	}

	progress := &Progress{JobId: "j", NodeId: "n", Percent: 12.5, Message: "msg", Data: []byte("d")}
	if progress.GetJobId() != "j" || progress.GetNodeId() != "n" || progress.GetPercent() != 12.5 || progress.GetMessage() != "msg" || string(progress.GetData()) != "d" {
		t.Fatal("Progress getters")
	}

	jobErr := &JobError{Code: "E1", Message: "boom"}
	if jobErr.GetCode() != "E1" || jobErr.GetMessage() != "boom" {
		t.Fatal("JobError getters")
	}

	result := &Result{
		JobId:  "j",
		Status: "ok",
		Output: map[string]*Ref{"out": ref},
		Error:  jobErr,
	}
	if result.GetJobId() != "j" || result.GetStatus() != "ok" || result.GetOutput()["out"] == nil || result.GetError() == nil {
		t.Fatal("Result getters")
	}

	// oneof variant 1: progress
	evProg := &Event{Payload: &Event_Progress{Progress: progress}}
	if evProg.GetPayload() == nil || evProg.GetProgress() == nil || evProg.GetResult() != nil {
		t.Fatal("Event progress oneof")
	}
	// oneof variant 2: result
	evRes := &Event{Payload: &Event_Result{Result: result}}
	if evRes.GetPayload() == nil || evRes.GetResult() == nil || evRes.GetProgress() != nil {
		t.Fatal("Event result oneof")
	}

	nodeRoundTrip(t, getManReq, &GetManifestRequest{})
	nodeRoundTrip(t, port, &Port{})
	nodeRoundTrip(t, man, &Manifest{})
	nodeRoundTrip(t, ref, &Ref{})
	nodeRoundTrip(t, job, &Job{})
	nodeRoundTrip(t, progress, &Progress{})
	nodeRoundTrip(t, jobErr, &JobError{})
	nodeRoundTrip(t, result, &Result{})
	nodeRoundTrip(t, evProg, &Event{})
	nodeRoundTrip(t, evRes, &Event{})
}

// TestNodeNilGetters exercises nil-receiver guard branches.
func TestNodeNilGetters(t *testing.T) {
	var j *Job
	_ = j.GetJobId()
	_ = j.GetInput()
	_ = j.GetEnv()
	var r *Result
	_ = r.GetOutput()
	_ = r.GetError()
	var ev *Event
	_ = ev.GetPayload()
	_ = ev.GetProgress()
	_ = ev.GetResult()
}
